// Generate availability display
const bookings = $input.all();
const today = new Date();
today.setHours(0, 0, 0, 0);

// Create time slots from 10 AM to 2 AM
const slots = [];
for (let hour = 10; hour < 26; hour++) {
  const actualHour = hour >= 24 ? hour - 24 : hour;
  const slotDate = new Date(today);
  if (hour >= 24) {
    slotDate.setDate(slotDate.getDate() + 1);
  }
  slotDate.setHours(actualHour, 0, 0, 0);

  const timeString = slotDate.toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  });

  slots.push({ time: timeString, available: true });
}

// Mark booked slots as unavailable
const todayString = today.toISOString().split('T')[0];
bookings.forEach(booking => {
  if (booking.json && booking.json.Date === todayString && booking.json.Status === 'Confirmed') {
    const bookingTime = booking.json['Start Time'];
    slots.forEach(slot => {
      if (slot.time === bookingTime) {
        slot.available = false;
      }
    });
  }
});

// Create message
const available = slots.filter(s => s.available);
const booked = slots.filter(s => !s.available);

let message = `📅 Today's Availability (${today.toLocaleDateString()})\n\n`;
message += `✅ Available Slots:\n`;

if (available.length > 0) {
  available.forEach(slot => {
    message += `• ${slot.time}\n`;
  });
} else {
  message += `• No slots available today\n`;
}

if (booked.length > 0) {
  message += `\n❌ Booked Slots:\n`;
  booked.forEach(slot => {
    message += `• ${slot.time}\n`;
  });
}

message += `\n💡 To book, just tell me: "Book for [time]" or "I want [X] hours at [time]"`;

return [{ json: { message } }];

// Parse Gemini response and extract intent
const geminiResponse = $json;
let aiResponse;

try {
  const responseText = geminiResponse.candidates[0].content.parts[0].text;
  // Clean the response text (remove markdown formatting if present)
  const cleanText = responseText.replace(/```json|```/g, '').trim();
  aiResponse = JSON.parse(cleanText);
} catch (error) {
  console.log('Failed to parse AI response, using fallback');
  aiResponse = {
    intent: 'general_inquiry',
    requested_date: null,
    requested_time: null,
    duration_hours: 1,
    response_message: 'I\'m here to help with cricket bookings! Please tell me when you\'d like to play.'
  };
}

return [{ json: aiResponse }];

// Check for booking conflicts and validate request
const aiData = $('Parse AI Response').item.json;
const existingBookings = $input.all();
const userMessage = $('Telegram Trigger').item.json.message;

const requestedDate = aiData.requested_date;
const requestedTime = aiData.requested_time;
const duration = aiData.duration_hours || 1;

// Validate we have date and time
if (!requestedDate || !requestedTime) {
  return [{
    json: {
      status: 'need_clarification',
      message: `🤔 I'd love to help you book! Could you please specify:\n\n📅 Date: When would you like to play?\n⏰ Time: What time works for you?\n⏱️ Duration: How many hours? (minimum 1 hour)\n\nExample: "Book for tomorrow 6 PM for 2 hours"`
    }
  }];
}

// Check for conflicts
const hasConflict = existingBookings.some(booking => {
  if (!booking.json || booking.json.Status !== 'Confirmed') return false;
  return booking.json.Date === requestedDate && booking.json['Start Time'] === requestedTime;
});

if (hasConflict) {
  return [{
    json: {
      status: 'conflict',
      message: `❌ Sorry, that time slot is already booked!\n\n📅 Date: ${requestedDate}\n⏰ Time: ${requestedTime}\n\nWould you like to see available slots instead?`
    }
  }];
}

// Calculate cost
const cost = duration === 1 ? 25 : 
             duration === 2 ? 45 :
             duration === 3 ? 65 :
             duration * 20;

// Slot is available
return [{
  json: {
    status: 'available',
    message: `✅ Great! This slot is available:\n\n📅 Date: ${requestedDate}\n⏰ Time: ${requestedTime}\n⏱️ Duration: ${duration} hour(s)\n💰 Total Cost: $${cost}\n\nTo confirm this booking, please provide:\n👤 Your full name\n📱 Phone number\n👥 Number of players\n\nReply with: "[Your Name], [Phone], [Number of Players]"`,
    bookingDetails: {
      date: requestedDate,
      time: requestedTime,
      duration: duration,
      cost: cost,
      userId: userMessage.from.id,
      username: userMessage.from.username || userMessage.from.first_name
    }
  }
}];

// Parse user details extraction response
const geminiResponse = $json;
let userDetails;

try {
  const responseText = geminiResponse.candidates[0].content.parts[0].text;
  const cleanText = responseText.replace(/```json|```/g, '').trim();
  userDetails = JSON.parse(cleanText);
} catch (error) {
  console.log('Failed to parse user details, using fallback');
  userDetails = {
    has_all_details: false,
    full_name: null,
    phone_number: null,
    player_count: null,
    response_message: 'Please provide your details in this format: "Your Name, Phone Number, Number of Players"'
  };
}

return [{ json: userDetails }];

// Create final booking confirmation
const userDetails = $('Parse User Details').item.json;
const pendingBookings = $input.all();
const userId = $('Telegram Trigger').item.json.message.from.id;

// Find user's pending booking
const pendingBooking = pendingBookings.find(booking => 
  booking.json && 
  booking.json['User ID'] && 
  booking.json['User ID'].toString() === userId.toString() &&
  booking.json.Status === 'Awaiting Details'
);

if (!pendingBooking) {
  return [{
    json: {
      error: true,
      message: "❌ No pending booking found. Please start a new booking request."
    }
  }];
}

// Generate booking ID
const bookingId = `BCB${Date.now().toString().slice(-8)}`;

// Create final booking data
const finalBooking = {
  bookingId: bookingId,
  date: pendingBooking.json.Date,
  time: pendingBooking.json.Time,
  duration: pendingBooking.json.Duration,
  cost: pendingBooking.json.Cost,
  customerName: userDetails.full_name,
  phone: userDetails.phone_number,
  players: userDetails.player_count,
  userId: userId,
  username: pendingBooking.json.Username,
  status: 'Confirmed'
};

// Create confirmation message
const confirmationMessage = `🎉 Booking Confirmed! 🏏\n\n📋 Booking Details:\n🆔 Booking ID: ${bookingId}\n👤 Name: ${userDetails.full_name}\n📱 Phone: ${userDetails.phone_number}\n👥 Players: ${userDetails.player_count}\n\n📅 Date: ${finalBooking.date}\n⏰ Time: ${finalBooking.time}\n⏱️ Duration: ${finalBooking.duration} hour(s)\n💰 Total Cost: $${finalBooking.cost}\n\n📍 Premium Box Cricket Facility\n🅿️ Free parking available\n\n📝 Important:\n• Arrive 10 minutes early\n• All equipment provided\n• Payment at facility\n\nSee you on the pitch! 🏏⚡`;

// Admin notification
const adminMessage = `🚨 NEW BOOKING\n\nID: ${bookingId}\nCustomer: ${userDetails.full_name}\nPhone: ${userDetails.phone_number}\nDate: ${finalBooking.date}\nTime: ${finalBooking.time}\nRevenue: $${finalBooking.cost}`;

return [{
  json: {
    error: false,
    confirmationMessage: confirmationMessage,
    adminMessage: adminMessage,
    finalBooking: finalBooking
  }
}];
